#include <iostream>
#include <mutex>
#include <atomic>

class DoubleCheckedSingleton {
private:
    // atomic prevents reordering of the three steps behind "new":
    // allocate memory, call constructor, assign pointer
    static std::atomic<DoubleCheckedSingleton*> instance;
    static std::mutex mtx;

    DoubleCheckedSingleton() {}

public:
    DoubleCheckedSingleton(const DoubleCheckedSingleton&) = delete;
    DoubleCheckedSingleton& operator=(const DoubleCheckedSingleton&) = delete;

    static DoubleCheckedSingleton* getInstance() {
        // Fast path: first check without locking
        DoubleCheckedSingleton* tmp = instance.load(std::memory_order_acquire);
        if (tmp == nullptr) {
            std::lock_guard<std::mutex> lock(mtx);
            tmp = instance.load(std::memory_order_relaxed);
            // Second check inside the lock (prevents double creation)
            if (tmp == nullptr) {
                tmp = new DoubleCheckedSingleton();
                instance.store(tmp, std::memory_order_release);
            }
        }
        return tmp;
    }
};

std::atomic<DoubleCheckedSingleton*> DoubleCheckedSingleton::instance{nullptr};
std::mutex DoubleCheckedSingleton::mtx;

int main() {
    DoubleCheckedSingleton* a = DoubleCheckedSingleton::getInstance();
    DoubleCheckedSingleton* b = DoubleCheckedSingleton::getInstance();

    std::cout << std::boolalpha << "Same instance? " << (a == b) << std::endl;
    return 0;
}

