#include <iostream>

class EnumSingleton {
private:
    EnumSingleton() {}

public:
    EnumSingleton(const EnumSingleton&) = delete;
    EnumSingleton& operator=(const EnumSingleton&) = delete;

    // C++ has no enum-with-methods idiom like Java; a function-local static
    // instance is the closest safe, simple global access point.
    static EnumSingleton& instance() {
        static EnumSingleton INSTANCE;
        return INSTANCE;
    }

    void doSomething() {
        std::cout << "Singleton doing something." << std::endl;
    }
};

int main() {
    EnumSingleton::instance().doSomething();

    std::cout << std::boolalpha << "Same instance? "
              << (&EnumSingleton::instance() == &EnumSingleton::instance()) << std::endl;
    return 0;
}

