import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;

enum Logger {
    INSTANCE;

    private static final DateTimeFormatter formatter =
        DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");

    public void log(String level, String message) {
        String timestamp = LocalDateTime.now().format(formatter);
        System.out.println("[" + timestamp + "] [" + level + "] " + message);
    }

    public void info(String message) {
        log("INFO", message);
    }

    public void warn(String message) {
        log("WARN", message);
    }

    public void error(String message) {
        log("ERROR", message);
    }
}

// --- Main ---
public class Main {
    public static void main(String[] args) {
        // Both references point to the same Logger instance
        Logger logger1 = Logger.INSTANCE;
        Logger logger2 = Logger.INSTANCE;

        System.out.println("Same instance? " + (logger1 == logger2)); // true

        // Different components logging through the same instance
        logger1.info("User:42 logged in successfully");
        logger2.warn("Payment retry attempt for Order:99");
        logger1.error("Database connection timeout");
        logger2.info("Background job completed");
    }
}

