#include <iostream>
#include <string>
#include <chrono>
#include <ctime>
#include <sstream>
#include <iomanip>

class Logger {
private:
    Logger() {}

    static std::string timestamp() {
        auto now = std::chrono::system_clock::now();
        std::time_t t = std::chrono::system_clock::to_time_t(now);
        std::tm tm = *std::localtime(&t);
        std::ostringstream oss;
        oss << std::put_time(&tm, "%Y-%m-%d %H:%M:%S");
        return oss.str();
    }

public:
    Logger(const Logger&) = delete;
    Logger& operator=(const Logger&) = delete;

    static Logger& instance() {
        static Logger INSTANCE;
        return INSTANCE;
    }

    void log(const std::string& level, const std::string& message) {
        std::cout << "[" << timestamp() << "] [" << level << "] " << message << std::endl;
    }

    void info(const std::string& message) { log("INFO", message); }
    void warn(const std::string& message) { log("WARN", message); }
    void error(const std::string& message) { log("ERROR", message); }
};

int main() {
    // Both references point to the same Logger instance
    Logger& logger1 = Logger::instance();
    Logger& logger2 = Logger::instance();

    std::cout << std::boolalpha << "Same instance? " << (&logger1 == &logger2) << std::endl;

    // Different components logging through the same instance
    logger1.info("User:42 logged in successfully");
    logger2.warn("Payment retry attempt for Order:99");
    logger1.error("Database connection timeout");
    logger2.info("Background job completed");
    return 0;
}
